```java
import android.content.Context;
import android.location.Location;
import android.location.LocationManager;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        LocationManager locationManager = (LocationManager) getSystemService(Context.LOCATION_SERVICE);
        Location location = locationManager.getLastKnownLocation(LocationManager.GPS_PROVIDER);
        if (location != null) {
            long gpsTime = location.getGpsDate();
            Log.d("GNSS", "La marca de tiempo GNSS es: " + gpsTime);
            long systemTime = SystemClock.elapsedRealtime();
            Log.d("Android", "El tiempo del sistema Android es: " + systemTime);
            long timeDiff = gpsTime - systemTime;
            Log.d("Difference", "La diferencia entre la marca de tiempo GNSS y el tiempo del sistema Android es: " + timeDiff);
        }
    }
}
```

